        ...col,
        chats: columnChats[col.title] || col.chats || []
      })) || []
      board.last_update = new Date().toISOString()
    }
  },
})

// ─── Actions ─────────────────────────────────────────────────────────────────

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init() {
      // Initialize kanban store and set up project change listeners
      await $storex.kanban.setupProjectChangeListener()
    },

    setupProjectChangeListener() {
      // This will be called by the projects store when activeProject changes
      // We don't need to actively watch here, projects store will notify us
    },

    async onActiveProjectChanged() {
      // Called by projects store when activeProject changes
      $storex.kanban.resetOnProjectChange()
      await $storex.kanban.loadKanban()
    },

