        $storex.projects.saveKanban()
      }
      $storex.projects.setActiveBoard(title)
      return $storex.projects.allBoards.find(b => b.title === title)
    },
    async editBoard({ state }, { title, newTitle, description }) {
      const existingBoard = state.kanban.boards[title]
      existingBoard.description = description
      if (title !== newTitle) {
        if (!state.kanban.boards[newTitle]) {
          state.kanban.boards[newTitle] = existingBoard
          delete state.kanban.boards[title]    
        }
      }
      $storex.projects.saveKanban()
    },
    async deleteBoard({ state }, { id, title }) {
      delete state.kanban.boards[title]
      if (state.activeBoard == title) {
        state.activeBoard = null
      }
      await $storex.api.chats.kanban.delete(title)
      $storex.projects.saveKanban()
    },
    async searchMentions({ state }, { query, limit = 10, onResults, controller }) {
      const project = state.activeProject
      if (!project?.$state) return []
      return project.$state.searchMentions({ query, limit, onResults, controller })
    },
    async reloadMentions({ state }) {
      const project = state.activeProject
      if (!project?.$state) return

      const relatedProjects = getRelatedProjects(project)
      const allToReload = [project, ...relatedProjects]

      allToReload.forEach(clearMentionCache)

      await Promise.all(
        allToReload.map(p => Promise.all([
          ensureFilesLoaded(p, true),
          ensureProfilesLoaded(p, true),
        ]))
      )
    },
    async startIndexing({ commit }, { project, filePaths }) {
      $storex.projects.setIndexingFiles(filePaths)
      $storex.projects.setIndexingError(null)

      try {
        const api = project.$api
        if (!api) {
          throw new Error('API not initialized')
        }

        await api.knowledge.indexFilesBackground(filePaths)
      } catch (error) {
        $storex.projects.setIndexingError(error.message)
        throw error
      }
    },

    clearIndexing({ commit }) {
      commit('clearIndexingState')
    },

    subscribeToIndexProgress({ commit }) {
      const socket = $storex.api.socket
      if (!socket) {
        throw new Error('Socket not connected')
      }

      socket.on('codx-junior-index-progress-started', (data) => {
        console.log(`📦 Indexing started: ${data.total_files} files`)
        $storex.projects.updateIndexProgress({
          status: 'indexing',
          progress: 0,
          message: data.message,
        })
        $storex.ui.addNotification({ 
          text: `📦 Indexing started: ${data.total_files} files`,
          type: 'info'
        })
      })

      socket.on('codx-junior-index-progress-document-processing', (data) => {
        console.log(`📄 Processing: ${data.source}`)
        $storex.projects.updateIndexProgress({
          status: 'processing',
          progress: Math.round((data.file_index / data.total_files) * 100),
          current_file: data.source,
          stage: 'Loading documents',
        })
      })

      socket.on('codx-junior-index-progress-document-enriched', (data) => {
        console.log(`✨ Enriched: ${data.source} (${data.progress_percent}%)`)
        $storex.projects.updateIndexProgress({
          status: 'enriching',
          progress: data.progress_percent,
          completed: data.completed,
          total: data.total,
          stage: 'Enriching documents with AI',
        })
      })

      socket.on('codx-junior-index-progress-document-indexed', (data) => {
        console.log(`📚 Indexed: ${data.source} (${data.progress_percent}%)`)
        $storex.projects.updateIndexProgress({
          status: 'indexing_db',
          progress: data.progress_percent,
          indexed_count: data.indexed_count,
          total: data.total,
          stage: 'Writing to database',
        })
        $storex.ui.addNotification({ 
          text: `✅ Indexed: ${data.source}`,
          type: 'info'
        })
      })

      socket.on('codx-junior-index-progress-batch-complete', (data) => {
        console.log(`✅ Batch complete: ${data.documents_loaded} documents`)
        $storex.ui.addNotification({ 
          text: `✅ Batch complete: ${data.documents_loaded} documents`,
          type: 'info'
        })
      })

      socket.on('codx-junior-index-progress-completed', (data) => {
        console.log(`🎉 Indexing complete: ${data.indexed_count}/${data.total}`)
        $storex.projects.updateIndexProgress({
          status: 'complete',
          progress: 100,
          message: `Successfully indexed ${data.indexed_count} documents`,
        })
        $storex.ui.addNotification({ 
          text: `🎉 Indexing complete: ${data.indexed_count}/${data.total} documents`,
          type: 'info'
        })
        setTimeout(() => {
          commit('clearIndexingState')
        }, 2000)
      })

      socket.on('codx-junior-index-error', (data) => {
        console.error(`❌ Error: ${data.error_type} - ${data.message}`)
        $storex.projects.setIndexingError(data.message)
        $storex.projects.updateIndexProgress({
          status: 'error',
          error: data.message,
          context: data.context,
        })
        $storex.ui.addNotification({ 
          text: `❌ Indexing error: ${data.message}`,
          type: 'error'
        })
      })
    },

    unsubscribeFromIndexProgress() {
      const socket = $storex.api.socket
      if (!socket) return

      socket.off('codx-junior-index-progress-started')
      socket.off('codx-junior-index-progress-document-processing')
      socket.off('codx-junior-index-progress-document-enriched')
      socket.off('codx-junior-index-progress-document-indexed')
      socket.off('codx-junior-index-progress-batch-complete')
      socket.off('codx-junior-index-progress-completed')
      socket.off('codx-junior-index-error')
    },

    async saveLastActiveProject() {
      try {
        const projectId = $storex.projects?.activeProject?.project_id
        if (projectId) {
          localStorage.setItem('lastActiveProject', projectId)
        }
      } catch (error) {
        console.error('Failed to save last active project:', error)
      }
    },

    async initProjectState({ state }, project) {
      const targetProject = project || state.activeProject
      if (!targetProject) {
        throw new Error('No project provided or active project set')
      }

      // Ensure project is initialized
      if (!targetProject.$state) {
        targetProject.$state = createState()
        targetProject.$state.status = ENTITY_STATUS.UNINITIALIZED
      }

      // Initialize if not already done
      if (targetProject.$state.status === ENTITY_STATUS.UNINITIALIZED) {
        await initProject(targetProject)
      }

      return targetProject.$state
    },

    createSearchController() {
      return new MentionSearchController()
    }
  }
)

messages.content:
I can see the issue. There's a circular/recursive call happening in the `kanban.js` store. Looking at line 247 in the `setActiveBoard` action, it's calling `$storex.kanban.setActiveBoard()` which creates infinite recursion.

Let me trace the problem:

1. In `kanban.js` action `setActiveBoard`, after loading kanban, it calls `$storex.kanban.setActiveBoard(validBoard)` 
2. This calls the same action again, creating infinite recursion

The fix is to use the mutation directly instead of calling the action recursively.

```js src/store/kanban.js
    async setActiveBoard({ state }, boardName) {
      const kanban = getKanban()
      if (!kanban || !kanban.boards) {
        await $storex.kanban.loadKanban()
      }
      const validBoard = boardName && getKanban().boards?.[boardName] ? boardName : null
      $storex.kanban.setActiveBoard(validBoard)  // ← This is calling the action recursively
    },
```

**Changes needed:**

| File | Issue | Fix |
|------|-------|-----|
| `src/store/kanban.js` | Line 247: `setActiveBoard` action calls itself recursively | Change `$storex.kanban.setActiveBoard()` to `mutations.setActiveBoard()` or use commit |
| `src/store/kanban.js` | Multiple other actions have same issue | Replace action calls to mutations with direct mutation calls |

```js src/store/kanban.js
export const actions = actionTree(
  { state, getters, mutations },
  {
    async init() {
    },

    async onActiveProjectChanged() {
      // Called by projects store when activeProject changes
      $storex.kanban.resetOnProjectChange()
      await $storex.kanban.loadKanban()
    },

    resetOnProjectChange() {
      mutations.setActiveBoard(state, null)
      mutations.setFilter(state, null)
    },

    async setActiveBoard({ state }, boardName) {
      const kanban = getKanban()
      if (!kanban || !kanban.boards) {
        await $storex.kanban.loadKanban()
      }
      const validBoard = boardName && getKanban().boards?.[boardName] ? boardName : null
      mutations.setActiveBoard(state, validBoard)
    },

    async loadKanban({ state }, project) {
      const targetProject = getActiveProject(project)
      if (!targetProject?.$api) return
      const kanban = await targetProject.$api.chats.kanban.load()
      if (!targetProject.$state) return
      targetProject.$state.kanban = kanban
      return kanban
    },

    async saveKanban({ state }, project) {
      const targetProject = getActiveProject(project)
      if (!targetProject?.$api) return
      const data = getKanban(targetProject)
      await targetProject.$api.chats.kanban.save(data)
    },

    async addColumn({ state }, { title, color, project_id }) {
      const board = getKanban().boards?.[state.activeBoard]
      if (!board) return
      title = title?.trim()
      if (!title) return

      const exists = board.columns?.find(c => c.title === title)
      if (exists) return

      mutations.addColumn(state, {
        boardId: state.activeBoard,
        column: {
          id: uuidv4(),
          title,
          color: color || null,
          project_id: project_id || null,
          chats: []
        }
      })
      await $storex.kanban.saveKanban()
    },

    async updateColumn({ state }, { id, title, color, project_id }) {
      const board = getKanban().boards?.[state.activeBoard]
      if (!board) return

      mutations.updateColumn(state, {
        boardId: state.activeBoard,
        columnId: id,
        updates: {
          title: title?.trim(),
          color: color !== undefined ? color : undefined,
          project_id: project_id !== undefined ? project_id : undefined
        }
      })
      await $storex.kanban.saveKanban()
    },

    async deleteColumn({ state, getters }, { title }) {
      const board = getKanban().boards?.[state.activeBoard]
      if (!board) return

      const col = getters.viewColumns.find(c => c.title === title)
      if (col?.tasks?.length) {
        await Promise.all(col.tasks.map(chat => $storex.chats.deleteChat(chat)))
      }

      mutations.removeColumn(state, {
        boardId: state.activeBoard,
        columnTitle: title
      })
      await $storex.kanban.saveKanban()
    },

    async syncColumnOrder({ state, getters }, viewColumns) {
      const kanban = getKanban()
      const board = kanban.boards?.[state.activeBoard]
      if (!board) return

      const newColumns = await Promise.all(
        viewColumns.map(async (viewCol) => {
          const storeCol = getters.activeKanbanBoard?.columns?.find(
            c => c.id === viewCol.id || c.title === viewCol.title
          ) || {}

          await Promise.all(
            (viewCol.tasks || [])
              .filter(t => t.column !== viewCol.title)
              .map(task => $storex.chats.saveChatInfo({ ...task, column: viewCol.title }))
          )

          return {
            id: storeCol.id || viewCol.id,
            title: viewCol.title,
            color: storeCol.color || viewCol.color || null,
            project_id: storeCol.project_id || viewCol.project_id || null,
            showSubTasks: storeCol.showSubTasks,
            chats: (viewCol.tasks || []).map(t => t.id)
          }
        })
      )

      mutations.reorderColumns(state, {
        boardId: state.activeBoard,
        columns: newColumns
      })
      await $storex.kanban.saveKanban()
    },

    async moveTask({ state, getters }, { taskId, toColumn }) {
      const task = getters.boardChats.find(t => t.id === taskId)
      if (!task) return
      await $storex.chats.saveChatInfo({ ...task, column: toColumn })
    },

    async newTask({ state }, { mode, column, name, profiles, board }) {
      const chat = await $storex.chats.createNewChat({
        id: uuidv4(),
        mode: mode || 'chat',
        profiles: profiles || [],
        messages: [],
        name: name || null,
        board: board || state.activeBoard,
        column: column || null
      })
      return chat
    },

    async createSubTask({ state }, {
      parent, name, mode, description, project_id, parent_id,
      message_id, file_list, activateChat, child_index, column, profiles
    }) {
      const chat = await $storex.chats.createNewChat({
        id: uuidv4(),
        board: parent.board,
        name,
        mode,
        profiles: profiles || [],
        column: column || parent.column,
        parent_id: parent_id || parent.id,
        message_id,
        project_id: project_id || parent.project_id,
        messages: description ? [{ role: 'user', content: description }] : [],
        file_list,
        child_index
      })

      if (activateChat !== false) {
        await $storex.chats.setActiveChat(chat)
      }

      await $storex.chats.saveChat(chat)
      if (description) $storex.projects.chatWihProject(chat)
      return chat
    },

    async addBoard({ state }, { title, description, background, parent_id, project_id, columns }) {
      const kanban = getKanban()
      if (!kanban) return

      title = title?.trim()
      if (!title || kanban.boards?.[title]) return

      if (!kanban.boards) kanban.boards = {}
      kanban.boards[title] = {
        id: uuidv4(),
        title,
        description: description || '',
        background: background || '',
        parent_id: parent_id || null,
        project_id: project_id || null,
        columns: columns || [],
        last_update: new Date().toISOString()
      }

      await $storex.kanban.saveKanban()
      mutations.setActiveBoard(state, title)
      return kanban.boards[title]
    },

    async saveBoard({ state }, { originalTitle, board }) {
      const kanban = getKanban()
      const oldName = originalTitle
      const newName = board.title?.trim()
      if (!newName) return

      if (oldName && oldName !== newName) {
        const allChats = Object.values($storex.chats.chats || {})
        await Promise.all(
          allChats
            .filter(c => c.board === oldName)
            .map(c => $storex.chats.saveChatInfo({ ...c, board: newName }))
        )
        delete kanban.boards[oldName]
        Object.values(kanban.boards)
          .filter(b => b && b.parent_id === oldName)
          .forEach(b => (b.parent_id = newName))
      }

      kanban.boards[newName] = {
        ...kanban.boards[newName],
        title: newName,
        description: board.description || '',
        background: board.background || '',
        parent_id: board.parent_id || null,
        project_id: board.project_id || null
      }

      await $storex.kanban.saveKanban()

      if (oldName && oldName !== newName && state.activeBoard === oldName) {
        mutations.setActiveBoard(state, newName)
      }
    },

    async deleteBoard({ state }, board) {
      const kanban = getKanban()
      const boardTitle = board?.title || board
      if (!boardTitle || !kanban.boards?.[boardTitle]) return

      const boardChats = Object.values($storex.chats.chats || {})
        .filter(c => c.board === boardTitle)
      await Promise.all(boardChats.map(c => $storex.chats.deleteChat(c)))

      const childBoardsList = Object.values(kanban.boards)
        .filter(b => b && b.parent_id === boardTitle)
      for (const child of childBoardsList) {
        await $storex.kanban.deleteBoard(child)
      }

      mutations.deleteBoard(state, boardTitle)
      await $storex.kanban.saveKanban()

      if (state.activeBoard === boardTitle) {
        const fallback = board.parent_id || Object.keys(kanban.boards).find(k => kanban.boards[k] !== null) || null
        mutations.setActiveBoard(state, fallback)
      }
    },

    async toggleBookmark({ state }, boardTitle) {
      const kanban = getKanban()
      const board = kanban.boards?.[boardTitle || state.activeBoard]
      if (!board) return
      board.bookmark = !board.bookmark
      await $storex.kanban.saveKanban()
    },
  }
)
